pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that tracks balance via transferFrom
        Token token = new Token();
        address tokenAddr = address(token);
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 100;
        // Fund from with enough tokens
        token.mint(from, v);
        // Approve c to transfer from from
        vm.prank(from);
        token.approve(address(c), v);
        // Call transfer - reference uses call, bug uses delegatecall
        c.transfer(from, tokenAddr, tos, v);
        // Assert: after call, token balance of tos[0] increased by v; after delegatecall, it stays 0
        uint balanceAfter = token.balanceOf(tos[0]);
        assertTrue(balanceAfter == v, "Should be v with call, but 0 with delegatecall");
    }
}

contract Token {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) external { balanceOf[to] += amount; }
    function approve(address spender, uint amount) external { allowance[msg.sender][spender] = amount; }
    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

