pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // A minimal token that always reverts on transferFrom to ensure the loop inside C fails
    contract EvilToken {
        function transferFrom(address, address, uint256) external pure returns (bool) {
            revert("always revert");
        }
    }

    function setUp() public { 
        c = new C(); 
    }

    function testRegression_property() public {
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 1;

        bool ok;
        try c.transfer(from, address(new EvilToken()), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract will revert due to require(_s) inside the loop, so ok = false
        // Mutant contract returns false (default) without reverting, so ok = true
        assertTrue(!ok, "Reference must revert, mutant does not");
    }
}

