pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address caddress = address(0x2);
        address[] memory tos = new address[](0);
        bool ok;
        try c.transfer(from, caddress, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: transfers reverts because _tos.length > 0 fails, so catch sets ok=false
        // Bug: same revert, so ok=false — but wait, we compare returns? Let's instead check return value directly:
        // Actually both revert on empty tos. Need a difference on the return value.
        // Let's re-think: the bug deletes 'return true;', so when the function completes normally (with non-empty tos and successful calls), the reference returns true, the bug returns false (default).
        // Use a valid token that always succeeds, non-empty tos:
        // For simplicity, use a mock token that does nothing but returns true.
        // Since we cannot define another contract, we'll use the zero address (call to zero address returns success).
        address[] memory tos2 = new address[](1);
        tos2[0] = address(0xdead);
        bool res = c.transfer(from, address(0), tos2, 100);
        assertTrue(res == false); // Bug returns false, reference returns true, so this fails on reference and passes on bug? No, we need assertTrue that reference passes and bug fails.
        // Actually reference returns true, bug returns false. So we want assertTrue(res) for reference success, but bug fails.
        // But the test must pass on reference and fail on bug. So we assert res == true? Let's do:
        // assertTrue(res) would pass on reference (res=true) and fail on bug (res=false). That's correct.
        assertTrue(res);
    }
}

